/** Shape of mockup-fixtures.json (generated by tools/visual/extract-fixtures.mjs — never hand-edit the JSON). */
export interface TickerItem { html: string; cls: string; t: string; aid: number | null }
export interface FixtureBelief { stage: string; att: number; first?: string }
export interface FixtureAgent {
  id: number; name: string; age: number; job: string; x: number; y: number; heading: number; act: string;
  place: string | null; watch: boolean; beliefs: Record<string, FixtureBelief>;
  phone: { brand: string; tier: string; age: number; cond: string; batt: number };
  look: { skin: string; hair: string; shirt: string; pants: string; hairLong: boolean; cap: boolean };
  thoughts: { txt?: string }[];
}
export interface FixtureProduct {
  id: string; name: string; brand: string; price: number; hex: string; status: "draft" | "ready" | "live" | "ended";
  launched: number | null; sites: [string, number][]; stores: string[]; reel: number; reviewers: number;
}
export interface Fixtures {
  t: number; label: string;
  stats: { agents: number; households: number; rel: number; convToday: number; convTotal: number; thoughtsToday: number };
  ticker: TickerItem[];
  products: FixtureProduct[];
  agents: FixtureAgent[];
  featured: { id: number; thoughts: { txt: string }[] };
}

/** Load the fixtures lazily (keeps the 1.4 MB JSON out of the main chunk). */
export async function loadFixtures(): Promise<Fixtures> {
  const mod = await import("./mockup-fixtures.json");
  return (mod.default ?? mod) as unknown as Fixtures;
}
